from PIL import Image
import numpy as np
im=np.array(Image.open('first_frame.png').convert('RGB'))
# characterize masks likely blue, green, brown/potato, black
masks={
'green':(im[:,:,1]>im[:,:,0]*1.35)&(im[:,:,1]>im[:,:,2]*1.2),
'blue':(im[:,:,2]>im[:,:,0]*1.5)&(im[:,:,2]>im[:,:,1]*1.03),
'brown':(im[:,:,0]>im[:,:,2]*1.25)&(im[:,:,1]>im[:,:,2]*1.08),
'dark': im.mean(2)<45,
'white':im.mean(2)>220,
}
for n,m in masks.items():
 yy,xx=np.where(m); print(n,m.sum(), 'bbox', (xx.min(),yy.min(),xx.max(),yy.max()), 'cent', (xx.mean(),yy.mean()))
 print(' row counts top', sorted(enumerate(m.sum(1)),key=lambda z:z[1],reverse=True)[:12])
 print(' col counts top', sorted(enumerate(m.sum(0)),key=lambda z:z[1],reverse=True)[:12])
